// spec: specs/calculator.md (5.1–5.3) · кейсы: .qa/tests/calculator/CALC-SCREEN-01.md, CALC-SCREEN-05.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение.
// #359741: у не-админа пункта «מדריכים» нет — за калькулятором сразу «פרסום עסק למכירה» (у админа «מדריכים» между ними).
// Источник: #aeae17 «מה רצוי» «לשנות את שם הפריט בתפריט ל-«מחשבון רכישת עסק»» (мобильное меню — 4-й пункт, шапка десктопа);
// комментарий программиста PR #195 — футер тоже «מחשבון רכישת עסק» (принято пользователем 2026-11-04); H1 /calculator не меняется.
// Мобильное меню: кнопка ☰ в banner с доступным именем «תפריט» (#2f6eef, PR #198) — ищем только с exact: true,
// иначе совпадёт и кнопка «פתח תפריט נגישות» (она вне banner);
// меню — Radix Sheet (dialog с заголовком «תפריט»), выезжает с анимацией: click ждёт стабильности элемента.
import { test, expect, Page } from '@playwright/test';
import { prepareReadOnly, LOAD } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

const NEW = 'מחשבון רכישת עסק';
const OLD = 'מחשבון כדאיות';
const H1 = 'מחשבון כדאיות רכישת עסק';
const NEXT = 'פרסום עסק למכירה';
const PAGES = ['/', '/search', '/calculator'] as const;

async function open(page: Page, path: string) {
  // Окно PWA «אל תחמיצו אף הזדמנות» на первом заходе — «אולי מאוחר יותר»; cookie — «חיוניים בלבד» (если баннер всё же показан).
  await page.addLocatorHandler(page.getByRole('button', { name: 'אולי מאוחר יותר' }), (b) => b.click());
  await page.addLocatorHandler(page.getByRole('button', { name: 'חיוניים בלבד' }), (b) => b.click());
  await page.goto(path);
}

async function expectCalculatorPage(page: Page) {
  await page.waitForURL(/\/calculator$/, LOAD);
  await expect(page.getByRole('heading', { level: 1, name: H1, exact: true }), 'H1 /calculator без изменений').toBeVisible(LOAD);
}

test.describe('Навигация — пункт калькулятора «מחשבון רכישת עסק»', () => {
  for (const path of PAGES) {
    test(`Шапка десктопа на ${path}: «${NEW}» → /calculator, старого «${OLD}» нет #aeae17 @desktop @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await open(page, path);
      const banner = page.getByRole('banner');
      const link = banner.getByRole('link', { name: NEW, exact: true });
      await expect(link, 'пункт в шапке').toBeVisible(LOAD);
      await expect(link).toHaveAttribute('href', '/calculator');
      await expect(banner, `в шапке нет «${OLD}»`).not.toContainText(OLD);
      const headerTexts = (await banner.getByRole('link').allInnerTexts()).map((t) => t.trim());
      expect(headerTexts[headerTexts.indexOf(NEW) + 1], `шапка: после «${NEW}» — «${NEXT}», «מדריכים» нет (#359741)`).toBe(NEXT);
      await expect(banner.getByRole('link', { name: /מדריכ/ }), 'в шапке нет «מדריכים» (#359741)').toHaveCount(0);

      const footer = page.getByRole('contentinfo');
      await expect(footer.getByRole('link', { name: NEW, exact: true }), 'ссылка в футере').toHaveAttribute('href', '/calculator');
      await expect(footer, `в футере нет «${OLD}»`).not.toContainText(OLD);

      await link.click();
      await expectCalculatorPage(page);
    });

    test(`Мобильное меню на ${path}: 4-й пункт «${NEW}» → /calculator, старого «${OLD}» нет #aeae17 @mobile @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await open(page, path);
      const menuButton = page.getByRole('banner').getByRole('button', { name: 'תפריט', exact: true }).filter({ visible: true });
      await expect(menuButton, 'одна видимая кнопка меню «תפריט» в шапке').toHaveCount(1, LOAD);
      await menuButton.click();

      const menu = page.getByRole('dialog').filter({ has: page.getByRole('heading', { name: 'תפריט', exact: true }) });
      await expect(menu, 'меню «תפריט» открыто').toBeVisible(LOAD);
      const items = menu.getByRole('link');
      await expect(items.nth(0), '1-й пункт').toHaveText('דף הבית');
      await expect(items.nth(3), '4-й пункт меню').toHaveText(NEW);
      await expect(items.nth(3)).toHaveAttribute('href', '/calculator');
      await expect(items.nth(4), `5-й пункт — «${NEXT}» (у гостя нет «מדריכים», #359741)`).toHaveText(NEXT);
      await expect(menu.getByRole('link', { name: /מדריכ/ }), 'в меню нет «מדריכים» (#359741)').toHaveCount(0);
      await expect(menu, `в меню нет «${OLD}»`).not.toContainText(OLD);

      await items.nth(3).click();
      await expectCalculatorPage(page);
    });
  }

  test(`Футер на /calculator: «${NEW}» → /calculator #aeae17 @desktop @prod-safe`, async ({ page, context }) => {
    await prepareReadOnly(context);
    await open(page, '/calculator');
    await expect(page.getByRole('heading', { level: 1, name: H1, exact: true })).toBeVisible(LOAD);
    const link = page.getByRole('contentinfo').getByRole('link', { name: NEW, exact: true });
    await expect(link).toHaveAttribute('href', '/calculator');
    await link.click();
    await expectCalculatorPage(page);
  });
});
